import {parsed,need,cid} from '../../utils/gradleOwnedCurrentSchema.js';import {ownedDigest as hash} from '../../utils/gradleOwnedJson.js';import {cprEntry,context,validatePlanCore,CPR_SPEC,CPR_SPEC_DIGEST,type CprContext,type CprRange} from './gradleOwnedCprASchema.js';import {layout,exact,makeTracked,newStats,type Stats} from './gradleOwnedCprAWire.js';
// Structural work units: <=19 final requests (8192 bytes + 4 ranges),
// <=76 accepted ranges + 19 failed group flush probes, <=13 binary trials each,
// and <=19 final arithmetic bound checks. This is not a CPU-time bound.
export const CPR_PLAN_WORK_BOUND=19*(8192+4)+(19*4+19)*13+19;
export function planCore(c:CprContext,seed:string,transferId:string,groups:CprRange[][]){return validatePlanCore({domain:'cpr.plan-core.v3',specDigest:CPR_SPEC_DIGEST,catalog:c.catalog,peer:c.peer,provider:c.provider,...(c.origin?{origin:c.origin}:{}),lineage:c.lineage,binding:c.binding,snapshot:c.snapshot,checkpoint:c.checkpoint,pin:c.pin,inventoryDigest:c.inventoryDigest,metadataDigest:c.metadataDigest,seed,transferId,groups});}
export function pack(input:unknown,entriesInput:unknown[],seedInput:string,transferInput:string,gate:()=>void=()=>{},s:Stats=newStats()){const c=context(input),seed=parsed(cid,seedInput),transferId=parsed(cid,transferInput),entries=entriesInput.map(e=>parsed(cprEntry,e));need(entries.length>=5&&entries.length<=9&&entries.reduce((n,e)=>n+e.byteLength,0)<=41460,'capacity_exhausted');let commits=0,payloads=0,payloadStarted=false;for(const e of entries){if(e.kind==='commit'){need(!payloadStarted&&e.index===commits++,'inventory_invalid');}else{payloadStarted=true;need(e.index===payloads++,'inventory_invalid');}}need(commits>0&&payloads>=4,'inventory_invalid');gate();const sizing=layout(c,seed,transferId,s),groups:CprRange[][]=[];let group:CprRange[]=[],used=0;s.phase='packing';
 for(const e of entries){let offset=0;while(offset<e.byteLength){gate();if(group.length===4||used===4096){groups.push(group);group=[];used=0;}need(groups.length<19,'capacity_exhausted');const upper=Math.min(e.byteLength-offset,4096-used),range=(length:number):CprRange=>({ordinal:group.length,kind:e.kind,index:e.index,offset,length,entry:{sha256:e.sha256,byteLength:e.byteLength}});let lo=1,hi=upper,best=0;while(lo<=hi){gate();const n=Math.floor((lo+hi)/2);if(sizing.bound([...group,range(n)]).fits){best=n;lo=n+1;}else hi=n-1;}if(!best){need(group.length>0,'wire_budget');groups.push(group);group=[];used=0;continue;}group.push(range(best));offset+=best;used+=best;}}
 if(group.length)groups.push(group);need(groups.length<=19,'capacity_exhausted');s.phase='final';gate();const core=planCore(c,seed,transferId,groups),digest=hash(core),commands=groups.map((rs,i)=>{gate();return makeTracked(c,seed,transferId,i,groups.length,digest,rs,s);});let wireBytes=0,workUnits=0;const bounds=commands.map(q=>{gate();const bound=sizing.bound(q.payload.ranges),actual=exact(c,q,s);need(actual.request<=bound.request&&actual.reply<=bound.reply&&actual.frames.every((n,i)=>n<=bound.frames[i]!)&&bound.fits,'layout_mismatch');wireBytes+=bound.total;workUnits+=actual.request+q.payload.ranges.length;return bound;});need(wireBytes<=CPR_SPEC.wireBytes&&workUnits<=CPR_SPEC.workUnits,'capacity_exhausted');gate();return {core,planDigest:digest,commands,bounds,wireBytes,workUnits,stats:s};}
